const text = $('Telegram Trigger').first().json.message.text.toUpperCase();
const match = text.match(/\b[A-Z]{1,5}\b/);
const ticker = match ? match[0] : 'AAPL';
return [{ json: { ticker } }];

// n8n Code Node — Name: Build Chart Data (v3 — SIMPLE)
// Place: Get Price - Yahoo → Build Chart Data
// This node MUST be connected directly after Get Price - Yahoo.
// It reads ONLY $json (its own input). No $('...') at all.

// 1. Yahoo data — sudhu ei node-er input theke ($json)
const priceJson = $json;

const result = priceJson && priceJson.chart && priceJson.chart.result
  ? priceJson.chart.result[0]
  : null;

if (!result || !Array.isArray(result.timestamp)) {
  throw new Error('Yahoo price data not found in $json — check that this Code node is connected directly after Get Price - Yahoo, and that Get Price - Yahoo is green with JSON output.');
}

const timestamps = result.timestamp || [];
const closesRaw = (result.indicators
  && result.indicators.quote
  && result.indicators.quote[0]
  && result.indicators.quote[0].close) || [];

// 2. Ticker + currency — Yahoo meta theke, onno node lagbe na
const ticker = (result.meta && result.meta.symbol) || 'AAPL';
const currency = (result.meta && result.meta.currency) || 'USD';
const currencySymbol = currency === 'USD' ? '$' : currency + ' ';

// 3. null close bad dao, date + price jora rakho
const points = [];
for (let i = 0; i < timestamps.length; i++) {
  const close = closesRaw[i];
  if (typeof close !== 'number' || isNaN(close)) continue;
  points.push({
    date: new Date(timestamps[i] * 1000).toISOString().slice(0, 10),
    close: Math.round(close * 100) / 100,
  });
}

if (points.length < 55) {
  throw new Error('Price point kom (' + points.length + ' ta) — Get Price - Yahoo URL-e range=6mo thik ache kina dekho.');
}

// 4. Sesh 60 din nao
const last60 = points.slice(-60);

// 5. 50-Day Average
const ma50 = last60.map((p, i) => {
  if (i < 49) return null;
  let sum = 0;
  for (let j = i - 49; j <= i; j++) sum += last60[j].close;
  return Math.round((sum / 50) * 100) / 100;
});

// 6. Caption-er hisab
const currentPrice = last60[last60.length - 1].close;
const firstPrice = last60[0].close;
const changePct = Math.round(((currentPrice - firstPrice) / firstPrice) * 1000) / 10;
const changeSign = changePct >= 0 ? '+' : '';

// 7. QuickChart config
const chartConfig = {
  type: 'line',
  data: {
    labels: last60.map((p) => p.date),
    datasets: [
      {
        label: 'Close Price',
        data: last60.map((p) => p.close),
        borderColor: 'rgb(37, 99, 235)',
        fill: false,
        borderWidth: 2,
        pointRadius: 0,
      },
      {
        label: '50-Day Average',
        data: ma50,
        borderColor: 'rgb(249, 115, 22)',
        fill: false,
        borderWidth: 2,
        borderDash: [5, 5],
        pointRadius: 0,
      },
    ],
  },
  options: {
    title: { display: true, text: ticker + ' — Last 60 Trading Days', fontSize: 16 },
    legend: { display: true, position: 'top' },
    scales: {
      xAxes: [{ ticks: { maxTicksLimit: 8 } }],
      yAxes: [{ ticks: { beginAtZero: false } }],
    },
  },
};

// 8. QuickChart POST body
const quickChartBody = {
  backgroundColor: 'white',
  width: 800,
  height: 400,
  format: 'png',
  chart: chartConfig,
};

// 9. Telegram caption
const captionBase = ticker + ' — 60-Day Trend | Price: ' + currencySymbol + currentPrice
  + ' | 60d Change: ' + changeSign + changePct + '%';

return [{
  json: {
    ticker,
    currency,
    currentPrice,
    changePct60d: changePct,
    startDate: last60[0].date,
    endDate: last60[last60.length - 1].date,
    pointsUsed: last60.length,
    captionBase,
    quickChartBody,
    labels: last60.map((p) => p.date),
    closes: last60.map((p) => p.close),
    ma50,
  },
}];

